# Makefile.cc - compiles the 'file' utility#    (Thanks to Mike Haaland for this!)## This is for Microware's 3.2 compiler# The Link is done at the Object-Code Level# This program is compiled for OS-9/68K## Macros# CC 		= ccODIR	= /dd/cmdsOFILE	= fileEDITION = 4RDIR	= IDIR/OS9RFILES	= file.r readmagic.r help.r istar.r strextra.r strtoul.rCFLAGS	= -g -q -v=. -d_BSDLFLAGS	= $(CFLAGS) -e=$(EDITION)# LINK Command$(OFILE)		: $(RFILES)	chd $(RDIR) ; $(CC) $(RFILES) $(LFLAGS) -f=$(OFILE)# dependenciesfile.r			: file.c file.hreadmagic.r		: readmagic.c file.hhelp.r			: help.c file.histar.r			: istar.c file.hstrextra.r		: strextra.cstrtoul.r		: strtoul.c